editing:
root=Stack([
  Stack([
    TextContent("Put a list in order", "large-heavy"),
    TextContent("Changes stay in a local draft until you save.", "small"),
  ],"column","s"),
  EditableTable("items",[
    {type:"text",key:"title",header:"Name",width:170},
    {type:"number",key:"count",header:"Quantity",width:100},
    {type:"date-single",key:"date",header:"Date",width:150},
