map:
$place="first"
$included="none"
first={point:{id:"first",title:"Place one",lat:30.245,lng:120.164},src:"https://sdk-fixture.invalid/detail.jpg",alt:"Sculpture photograph",description:"Follow the figure and the light to a detail worth pausing for.",duration:"Allow 45 minutes",note:"Take in the whole from a distance, then move closer to the folds and carved marks. Make a note of the detail that catches your eye."}
second={point:{id:"second",title:"Place two",lat:30.251,lng:120.172},src:"https://sdk-fixture.invalid/object.jpg",alt:"Object photograph",description:"Read the object through its material and texture. The text wraps and the card grows with it.",duration:"Allow 30 minutes",note:"Look at the outline, proportions, and surface marks. Imagine how this object once fitted into everyday life."}
current=$place=="first"?first:second
route=[{lat:30.245,lng:120.164},{lat:30.248,lng:120.168},{lat:30.251,lng:120.172}]
root=Stack([
  Stack([TextContent("Maps & places", "large-heavy"),TextContent("Two discoveries for an unhurried afternoon.", "small")],"column","s"),
  Map([first.point,second.point],[route],$place,"regular","gcj02",{
    first:Card([Stack([
      ImageText(first.src,first.alt,"About place one",first.description,true,"horizontal",64),
      TextContent(first.duration+" · take your time","small")
    ],"column","s")]),
    second:Card([Stack([
      ImageText(second.src,second.alt,"About place two",second.description,true,"horizontal",64),
      TextContent(second.duration+" · notice the texture","small")
    ],"column","s")])
  }),
  Tabs([
    TabItem("notes","What to look for",[
      TextContent("Now viewing: "+current.point.title,"small-heavy"),
      MarkDownRenderer(current.note,"clear"),
      EntityList([{left:"Visit",right:current.duration},{left:"Plan",right:"Take your time and leave some room"}],"small")
    ]),
    TabItem("prepare","Before you go",[
      CompositeCardBlock([CompositeCardItem("prepare",null,[
        ListBlock([
          ListItem("Check today's opening information","Check current opening times and reservation requirements before leaving."),
          ListItem("Allow for travel and rest","The map shows the supplied route, without live navigation advice.")
        ],"number","small")
      ],{button:Button($included==$place?"Already in this plan":"Add to this plan",@Set($included,$place),"secondary")})]),
      $included==$place?TextContent("Added to plan: "+current.point.title,"small"):null
    ])
  ]),
  Button("Select place two",@Set($place,"second"),"tertiary"),
  TextContent("Sample coordinates and routes demonstrate interactions, not live navigation.","small")
],"column","l")

